'use client';

import { useEffect, useState } from 'react';
import { Bookmark, FileImage, FileText, Heart, MessageCircle, MoreHorizontal, Paperclip, Send, Share2, Sparkles, Upload, X } from 'lucide-react';
import { AppShell, Avatar } from '@/components/doc-campus-shell';
import { api, Post, User } from '@/lib/doc-campus-api';

type Summary = Pick<User, 'id' | 'username' | 'avatarUrl'>;
type FeedResponse = { items: Post[]; nextCursor: string | null; hasNextPage: boolean };
function timeAgo(value: string) { const seconds = Math.max(1, Math.floor((Date.now() - new Date(value).getTime()) / 1000)); if (seconds < 60) return `${seconds}s`; if (seconds < 3600) return `${Math.floor(seconds / 60)}m`; if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`; return `${Math.floor(seconds / 86400)}d`; }

function PostCard({ post }: { post: Post }) {
  const isImage = post.fileType === 'image';
  return <article className="post-card"><div className="post-header"><Avatar username={post.author.username} src={post.author.avatarUrl} /><div className="post-author"><strong>{post.author.username}</strong><span>shared a {post.fileType} <b>·</b> {timeAgo(post.createdAt)}</span></div><button className="icon-button quiet"><MoreHorizontal size={18} /></button></div>{post.description && <p className="post-copy">{post.description}</p>}<a className={`attachment ${isImage ? 'attachment-image' : ''}`} href={post.fileUrl} target="_blank" rel="noreferrer">{isImage ? <img src={post.fileUrl} alt={post.description || 'Shared document'} /> : <><span className={`file-icon ${post.fileType}`}><FileText size={24} /></span><span><strong>{post.fileType.toUpperCase()} document</strong><small>{post.ocrStatus === 'done' ? 'Text extracted and ready to read' : 'Open document'}</small></span><span className="open-file">Open ↗</span></>}</a><div className="post-actions"><button title="Likes are coming with the interaction API"><Heart size={18} /> Like</button><button title="Comments are coming with the interaction API"><MessageCircle size={18} /> Comment</button><button><Share2 size={18} /> Share</button><button className="save-button"><Bookmark size={18} /> Save</button></div></article>;
}

function Composer({ onPosted }: { onPosted: () => void }) {
  const [file, setFile] = useState<File | null>(null); const [description, setDescription] = useState(''); const [open, setOpen] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!file) return setError('Choose a PDF, image, or document first.'); setBusy(true); setError(''); const form = new FormData(); form.append('file', file); if (description) form.append('description', description); try { await api('/api/posts', { method: 'POST', body: form }); setDescription(''); setFile(null); setOpen(false); onPosted(); } catch (caught) { setError(caught instanceof Error ? caught.message : 'Upload failed'); } finally { setBusy(false); } }
  return <section className={`composer ${open ? 'composer-open' : ''}`}><div className="composer-head"><Avatar username="D" /><button className="composer-prompt" onClick={() => setOpen(true)}>Share a document or a study note...</button></div>{open && <form onSubmit={submit}><textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What are you working on? Add context for your classmates..." maxLength={2000} autoFocus /><div className="composer-footer"><label className="upload-control"><Paperclip size={17} /> {file ? file.name : 'Attach file'}<input type="file" accept="image/*,.pdf,.doc,.docx" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><span className="char-count">{description.length}/2000</span><button className="primary-button" disabled={busy || !file}>{busy ? 'Uploading...' : 'Publish'} <Send size={16} /></button></div>{error && <p className="form-error">{error}</p>}<button type="button" className="composer-close" onClick={() => setOpen(false)}><X size={16} /></button></form>} {!open && <div className="composer-tools"><button onClick={() => setOpen(true)}><FileImage size={17} /> Photo</button><button onClick={() => setOpen(true)}><FileText size={17} /> Document</button><button onClick={() => setOpen(true)}><Sparkles size={17} /> Study note</button></div>}</section>;
}

export default function FeedPage() {
  const [summary, setSummary] = useState<Summary | null>(null); const [feed, setFeed] = useState<Post[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  async function load() { try { const [user, posts] = await Promise.all([api<Summary>('/api/users/me/summary'), api<FeedResponse>('/api/posts/feed?limit=10')]); setSummary(user); setFeed(posts.items); } catch (caught) { setError(caught instanceof Error ? caught.message : 'Could not load feed'); } finally { setLoading(false); } }
  useEffect(() => { load(); }, []);
  return <AppShell user={summary || undefined}><div className="feed-layout"><aside className="profile-sidebar"><section className="mini-profile"><div className="profile-cover" /><div className="mini-profile-body"><Avatar username={summary?.username || 'D'} src={summary?.avatarUrl} large /><h2>{summary?.username || 'Your profile'}</h2><p>Keep learning. Keep sharing.</p><div className="profile-stat"><span>0</span><small>documents shared</small></div><a href="/profile" className="text-link">View profile <span>→</span></a></div></section><section className="side-panel"><div className="side-heading"><span>YOUR LIBRARY</span><Bookmark size={14} /></div><a href="/saved"><Bookmark size={16} /> Saved documents <b>0</b></a><a href="/profile"><Upload size={16} /> Your uploads <b>{feed.filter((post) => post.author.id === summary?.id).length}</b></a></section></aside><div className="feed-main"><div className="page-intro"><div><p className="eyebrow">COMMUNITY FEED</p><h1>Learn out loud.</h1><p>Useful notes, resources, and ideas from your campus.</p></div></div><Composer onPosted={load} />{error && <div className="empty-state">{error}<button className="text-link" onClick={load}>Try again</button></div>}{loading ? <div className="loading-stack"><div /><div /><div /></div> : feed.length ? feed.map((post) => <PostCard key={post.id} post={post} />) : <div className="empty-state"><Sparkles size={24} /><h3>Your feed starts here</h3><p>Be the first to share a useful document with your campus.</p></div>}</div><aside className="right-rail"><section className="focus-card"><div className="focus-glow" /><p className="eyebrow">TODAY'S FOCUS</p><h3>Small notes compound into big understanding.</h3><p>Share what helped you today. Someone else is probably looking for it.</p><div className="focus-line" /></section><section className="right-list"><div className="side-heading"><span>QUICK START</span><Sparkles size={14} /></div><p><span>01</span> Upload a study resource</p><p><span>02</span> Add context for others</p><p><span>03</span> Find your next idea</p></section></aside></div></AppShell>;
}